function startBattle(){const p=place();state.mode='battle';state.battle={hp:p.hp,maxHp:p.hp,turn:1,log:`A ${p.enemy} bounds into your path!`,done:false};state.guard=false;render();}
function renderBattle(){const p=place(),b=state.battle;const won=b.hp<=0,lost=state.hp<=0;let result='';if(won||lost){b.done=true;result=`<div class="result-card"><div class="result-inner"><div class="result-symbol">${won?'✧':'☾'}</div><h2 class="result-title">${won?'A fine victory':'A gentle retreat'}</h2><p class="result-copy">${won?`The ${p.enemy} scampers away. You earned <b>${p.xp} XP</b> and <b>${p.shards} shards</b>.`:'The trail can wait. Your strength is restored so you can try again.'}</p><button class="btn primary" id="resultContinue">${won?'Return to the trail':'Get back up'} <span class="arrow">↗</span></button></div></div>`;}
$('mainContent').innerHTML=`<div class="page-head"><div><h1 class="page-title">A wild encounter</h1><div class="page-sub">A turn-based skirmish in ${p.name}</div></div><div class="season-pill">TURN &nbsp;${String(b.turn).padStart(2,'0')}</div></div><section class="battle-scene"><div class="battle-top"><span>FIELD ENCOUNTER &nbsp;·&nbsp; ${p.region.split(' · ')[0]}</span><span>✦ ${state.shards}</span></div><div class="enemy-wrap"><div class="enemy-art">${p.emoji}</div><div class="enemy-name">${p.enemy}</div><div class="meter"><span style="width:${Math.max(0,b.hp/b.maxHp*100)}%"></span></div><div class="enemy-hp">${Math.max(0,b.hp)} / ${b.maxHp} VIT</div></div><div class="hero-battle"><div class="hero-mini">🧭</div><div class="hero-hud"><b>Rin · Lv. ${state.level}</b><div class="meter hp"><span style="width:${Math.max(0,state.hp/state.maxHp*100)}%"></span></div><small>HP ${Math.max(0,state.hp)} / ${state.maxHp}</small><div class="meter mp"><span style="width:${state.mp/state.maxMp*100}%"></span></div><small>FOCUS ${state.mp} / ${state.maxMp}</small></div></div>${result}</section><div class="battle-log" id="battleLog">${b.log}</div><div class="battle-controls"><button class="battle-btn" data-action="strike" ${b.done?'disabled':''}><span class="sym">⚔</span><b>Strike</b><small>Quick, reliable hit</small></button><button class="battle-btn" data-action="skill" ${b.done||state.mp<6?'disabled':''}><span class="sym">✧</span><b>Wildspark</b><small>6 focus · Heavy hit</small></button><button class="battle-btn" data-action="guard" ${b.done?'disabled':''}><span class="sym">◈</span><b>Brace</b><small>Halve next damage</small></button><button class="battle-btn" data-action="potion" ${b.done||state.potions<1||state.hp===state.maxHp?'disabled':''}><span class="sym">⚗</span><b>Tonic <small style="display:inline">×${state.potions}</small></b><small>Restore 22 vitality</small></button></div><div class="combat-tip">Choose an action · Your focus recovers a little each round</div>`;
$('battleLog').textContent=b.log;$('mainContent').querySelectorAll('[data-action]').forEach(x=>x.onclick=()=>battleAction(x.dataset.action));if(b.done)$('resultContinue').onclick=()=>finishBattle(won);$('rightPanel').className='panel right-battle';$('rightPanel').innerHTML=`<section class="panel-section"><div class="panel-title">Encounter</div><div class="battle-turn">Turn ${b.turn}</div><div class="battle-turn-sub">${b.done?(won?'The creature has fled.':'You were overwhelmed.'):'Keep your footing. Every action can change the rhythm of a fight.'}</div><div class="loot-line">✧ ${p.xp} XP &nbsp; · &nbsp; ◈ ${p.shards} shards</div></section><section class="panel-section"><div class="panel-title">Your stance</div><div class="section-row"><div class="statbox"><div class="stat-number">${Math.max(0,state.hp)}</div><div class="stat-label">Vitality</div></div><div class="statbox"><div class="stat-number">${state.mp}</div><div class="stat-label">Focus</div></div></div><div style="font-size:10px;color:#94a192;line-height:1.55;margin-top:12px">${state.guard?'◈ Your guard is set; the next hit will be softened.':'◈ Bracing halves the next incoming hit.'}</div></section><div class="tips"><strong>COMBAT NOTE</strong>Wildspark hits hard, but a well-timed brace or tonic can keep you in the fight longer.</div>`;}
function battleAction(action){const p=place(),b=state.battle;if(!b||b.done)return;let msg='';if(action==='strike'){let dmg=8+state.level*2+Math.floor(Math.random()*5);b.hp-=dmg;msg=`You land a clean strike for ${dmg} damage.`;}else if(action==='skill'){if(state.mp<6)return;state.mp-=6;let dmg=17+state.level*3+Math.floor(Math.random()*6);b.hp-=dmg;msg=`Wildspark erupts for ${dmg} damage!`;}else if(action==='guard'){state.guard=true;msg='You brace yourself. The next hit will deal half damage.';}else if(action==='potion'){if(!state.potions||state.hp===state.maxHp)return;state.potions--;const healed=Math.min(22,state.maxHp-state.hp);state.hp+=healed;msg=`A warm tonic restores ${healed} vitality.`;}
if(b.hp<=0){b.log=msg;render();return;}const raw=p.attack+Math.floor(Math.random()*4);const dmg=state.guard?Math.ceil(raw/2):raw;state.hp=Math.max(0,state.hp-dmg);if(state.guard)state.guard=false;state.mp=Math.min(state.maxMp,state.mp+2);b.turn++;b.log=`${msg} ${p.enemy} ${state.hp?'strikes back for '+dmg+' damage.':'lands a final hit.'}`;render();}
function finishBattle(won){if(won){const p=place();state.shards+=p.shards;state.xp+=p.xp;state.quest++;state.cleared=[...new Set([...state.cleared,p.id])];if(state.xp>=[0,40,90,160,250][state.level]&&state.level<5){state.xp-=[0,40,90,160,250][state.level];state.level++;state.maxHp+=8;state.maxMp+=4;state.hp=state.maxHp;state.mp=state.maxMp;notify(`Level up! You reached level ${state.level}.`)}else notify(`Victory! +${p.xp} XP · +${p.shards} shards`);if(state.quest>=3&&!state.questRewarded){state.shards+=30;state.questRewarded=true;notify('Quest complete! +30 bonus shards.')}}else{state.hp=Math.ceil(state.maxHp*.7);state.mp=Math.ceil(state.maxMp*.7);notify('You caught your breath. Ready to try again.')};state.mode='world';state.battle=null;render();}
function gather(){const roll=Math.random();if(roll<.6){const amount=4+Math.floor(Math.random()*6);state.shards+=amount;notify(`You found ${amount} trail shards.`)}else if(roll<.85){state.potions++;notify('You gathered a field tonic.')}else{const p=place();state.hp=Math.min(state.maxHp,state.hp+8);$('fieldNote').textContent=`${p.flavor} The quiet restores 8 vitality.`;notify('A quiet moment restores 8 vitality.')}updateHeader();renderWorld();}
function rest(){const cost=5;if(state.shards<cost){notify('You need 5 shards to rest at camp.');return}state.shards-=cost;state.hp=state.maxHp;state.mp=state.maxMp;notify('Rested by the campfire. Vitality and focus restored.');render();}
function showInventory(){const grid=$('inventoryGrid');grid.innerHTML=`<div class="item-card"><div class="big">⚗</div><b>Field tonic</b><small>× ${state.potions} · +22 HP</small></div><div class="item-card"><div class="big">✦</div><b>Trail shards</b><small>× ${state.shards} · Currency</small></div><div class="item-card"><div class="big">🌿</div><b>Wild herbs</b><small>Foraged · keepsake</small></div>`;$('inventoryOverlay').classList.add('open');}
$('bagTab').onclick=showInventory;$('closeBag').onclick=()=>$('inventoryOverlay').classList.remove('open');$('bagDone').onclick=()=>$('inventoryOverlay').classList.remove('open');$('inventoryOverlay').onclick=e=>{if(e.target===$('inventoryOverlay'))$('inventoryOverlay').classList.remove('open')};$('worldTab').onclick=()=>{state.mode='world';$('inventoryOverlay').classList.remove('open');render()};render();
</script>
</body>
</html>

